(()=>{const dialog=document.querySelector('.gallery-dialog');if(!dialog)return;const links=[...document.querySelectorAll('.gallery-open')],img=dialog.querySelector('img'),count=dialog.querySelector('.gallery-count');let index=0,opener;function show(i){index=(i+links.length)%links.length;img.src=links[index].href;img.alt=links[index].querySelector('img').alt;count.textContent=`${index+1} / ${links.length}`}links.forEach((a,i)=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();opener=a;show(i);dialog.showModal();document.body.style.overflow='hidden'}));dialog.querySelector('.gallery-close').addEventListener('click',()=>dialog.close());dialog.querySelector('.gallery-prev').addEventListener('click',()=>show(index-1));dialog.querySelector('.gallery-next').addEventListener('click',()=>show(index+1));dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();show(index-1)}if(e.key==='ArrowRight'){e.preventDefault();show(index+1)}});dialog.addEventListener('close',()=>{document.body.style.overflow='';img.removeAttribute('src');opener?.focus()})})();
